package com.learningpal.service.ai;

import java.util.Locale;

/**
 * Validates that an evidence quote generated by the model is a faithful substring of the source section text.
 */
public class EvidenceVerifier {

    /**
     * Checks if the evidence quote is contained in the section text after whitespace, case,
     * and punctuation normalization.
     */
    public static boolean verifyQuote(String evidenceQuote, String sectionText) {
        if (evidenceQuote == null || evidenceQuote.isBlank() || sectionText == null || sectionText.isBlank()) {
            return false;
        }

        String normQuote = normalizeForComparison(evidenceQuote);
        String normSection = normalizeForComparison(sectionText);

        if (normQuote.isEmpty() || normQuote.length() < 10) {
            // Quotes shorter than 10 alphanumeric characters are considered too short or unsubstantial
            return false;
        }

        return normSection.contains(normQuote);
    }

    /**
     * Normalizes text by removing punctuation, collapsing consecutive whitespace, and lowercasing.
     */
    public static String normalizeForComparison(String text) {
        if (text == null) {
            return "";
        }
        // Replace non-alphanumeric characters with spaces
        String stripped = text.replaceAll("[^\\p{L}\\p{Nd}]+", " ").trim();
        // Collapse multiple spaces to single space
        stripped = stripped.replaceAll("\\s+", " ");
        return stripped.toLowerCase(Locale.ROOT);
    }
}
